const interactions = inputData.interactions || [];
const notionPages = inputData.notionPages || [];

const competitorKeywords = ['hubspot', 'salesforce', 'pipedrive', 'zoho', 'monday', 'asana', 'clickup', 'jira', 'linear'];
const competitorMentions = {};

const allText = [
  ...interactions.map(i => i.notes || ''),
  ...notionPages.map(p => p.content || '')
].join(' ').toLowerCase();

competitorKeywords.forEach(comp => {
  if (allText.includes(comp)) {
    competitorMentions[comp] = (allText.match(new RegExp(comp, 'gi')) || []).length;
  }
});

return {
  competitors_mentioned: Object.keys(competitorMentions),
  competitor_counts: competitorMentions,
  total_interactions: interactions.length,
  notion_pages_found: notionPages.length
};

